python3 -c "
from PIL import Image

img = Image.open('/home/robot/captures/top_001.png')
w, h = img.size

# Find the dark spots (bores) - they should be very dark circles
# Let's scan pixel by pixel looking for very dark pixels (bore centers might be very dark)
dark_spots = []
for y in range(h):
    for x in range(w):
        r, g, b = img.getpixel((x, y))
        if r < 30 and g < 30 and b < 30:
            dark_spots.append((x, y, r, g, b))

print(f'Found {len(dark_spots)} very dark pixels')
if dark_spots:
    # Cluster them
    clusters = []
    used = set()
    for i, (x, y, r, g, b) in enumerate(dark_spots):
        if i in used:
            continue
        cluster = [(x, y)]
        used.add(i)
        for j, (x2, y2, _, _, _) in enumerate(dark_spots):
            if j in used:
                continue
            if abs(x2 - x) < 10 and abs(y2 - y) < 10:
                cluster.append((x2, y2))
                used.add(j)
        if len(cluster) > 3:
            cx = sum(p[0] for p in cluster) / len(cluster)
            cy = sum(p[1] for p in cluster) / len(cluster)
            clusters.append((cx, cy, len(cluster)))

    print(f'Found {len(clusters)} clusters:')
    for cx, cy, size in clusters:
        print(f'  Dark spot at ({cx:.0f}, {cy:.0f}), size {size}')
"

